function renderChestCoronal(svg, view) {
  const ns = 'http://www.w3.org/2000/svg';
  const add = (tag, attrs) => {
    const node = document.createElementNS(ns, tag);
    for (const [key,value] of Object.entries(attrs)) node.setAttribute(key,value);
    svg.append(node);
    return node;
  };
  const overlay = chestNeutralOverlays[view.id];
  if (overlay) {
    const [x,y,width,height,pixels] = overlay;
    add('image',{x,y,width,height,href:'data:image/png;base64,'+pixels});
  }
  // Render the text columns from this view's transcription so the recorded
  // pointer and recorded selection outlines cannot masquerade as live input.
  for (const left of [true,false]) {
    const labels = view.annotations.filter(a=>a.label_dot && (a.label_dot.x<view.width/2)===left);
    const dots = labels.map(a=>a.label_dot.x);
    const edge = left ? Math.max(178,...dots)+30 : Math.min(1373,...dots)-30;
    add('rect',{x:left?0:edge,y:0,width:left?edge:view.width-edge,height:view.visibleHeight,fill:'#000'});
    for (const label of labels) {
      const {x,y}=label.label_dot;
      const sign=left?1:-1;
      add('line',{x1:x+16*sign,y1:y,x2:edge,y2:y,stroke:label.pin_color,'stroke-width':1});
      add('circle',{cx:x,cy:y,r:4.3,fill:label.pin_color});
      const tx=x+(left?-11:11), maxWidth=left?tx-3:view.width-tx-3;
      const node=add('text',{x:tx,'text-anchor':left?'end':'start',fill:'#d7dce2','font-family':'Arial, sans-serif','font-size':13,'font-weight':600});
      const lines=[''];
      for(const word of label.label_text.split(/\s+/)) {
        const last=lines.length-1, trial=(lines[last]+' '+word).trim();
        node.textContent=trial;
        if(lines[last] && node.getComputedTextLength()>maxWidth)lines.push(word);
        else lines[last]=trial;
      }
      node.textContent='';
      lines.forEach((line,i)=>{
        const span=document.createElementNS(ns,'tspan');
        span.setAttribute('x',tx);span.setAttribute('y',y+4+(i-(lines.length-1)/2)*14);
        span.textContent=line;node.append(span);
      });
    }
  }
}


